package com.tahamobiles.staff;
import org.junit.Test;
import org.junit.Rule;
import org.junit.rules.TemporaryFolder;
import org.json.JSONObject;
import org.json.JSONArray;
import java.io.File;
import java.nio.file.Files;
import java.util.UUID;
import static org.junit.Assert.*;
public class PendingPhotoPolicyTest{
 @Rule public TemporaryFolder temporary=new TemporaryFolder();
 private final String shop="http://192.168.1.8:3001";
 private String record(String id) throws Exception {return new JSONObject().put("captureId",id).put("requestId",UUID.randomUUID().toString()).put("shop",shop+"/api/v1").put("createdAt",System.currentTimeMillis()).put("data","data:image/jpeg;base64,AQIDBA==").toString();}
 @Test public void captureFilesUseOnlyUuidNames(){assertTrue(PendingPhotos.validId("8f7a155a-073a-4822-9ed3-294c458091fa"));for(String id:new String[]{"../secret","/photo","foo.json","8f7a155a-073a-4822-9ed3-294c458091fa/../secret",""})assertFalse(PendingPhotos.validId(id));}
 @Test public void pendingPhotoIsBinaryAndSurvivesRestartOnlyForSameShop() throws Exception {File root=temporary.newFolder();String id=UUID.randomUUID().toString();assertTrue(new PendingPhotos(root).save(record(id),shop));File folder=new File(root,"pending-photos");assertArrayEquals(new byte[]{1,2,3,4},Files.readAllBytes(new File(folder,id+".photo").toPath()));assertFalse(new String(Files.readAllBytes(new File(folder,id+".json").toPath()),java.nio.charset.StandardCharsets.UTF_8).contains("data:image"));PendingPhotos restarted=new PendingPhotos(root);assertEquals(1,new JSONArray(restarted.read(shop)).length());assertEquals(0,new JSONArray(restarted.read("http://192.168.1.9:3001")).length());restarted.remove(id);assertEquals(0,new JSONArray(restarted.read(shop)).length());}
 @Test public void queueIsBoundedAndLogoutClearsFiles() throws Exception {File root=temporary.newFolder();PendingPhotos photos=new PendingPhotos(root);for(int i=0;i<12;i++)assertTrue(photos.save(record(UUID.randomUUID().toString()),shop));assertFalse(photos.save(record(UUID.randomUUID().toString()),shop));photos.clear();assertEquals(0,new File(root,"pending-photos").listFiles().length);}
 @Test public void olderPhotosStayRecoverableAndWrongOriginCannotSave() throws Exception {File root=temporary.newFolder();PendingPhotos photos=new PendingPhotos(root);String id=UUID.randomUUID().toString();assertFalse(photos.save(record(id),"http://192.168.1.9:3001"));assertTrue(photos.save(record(id),shop));for(File f:new File(root,"pending-photos").listFiles())assertTrue(f.setLastModified(System.currentTimeMillis()-31*60*1000));assertEquals(1,new JSONArray(photos.read(shop)).length());}
 @Test public void corruptMetadataDoesNotHideHealthyPhotosAfterRestart() throws Exception {File root=temporary.newFolder();PendingPhotos photos=new PendingPhotos(root);String broken=UUID.randomUUID().toString(),first=UUID.randomUUID().toString(),last=UUID.randomUUID().toString();for(String id:new String[]{broken,first,last})assertTrue(photos.save(record(id),shop));File firstMetadata=new File(root,"pending-photos").listFiles((directory,name)->name.endsWith(".json"))[0];broken=firstMetadata.getName().replace(".json","");Files.write(firstMetadata.toPath(),new byte[]{0,0,0});JSONArray retained=new JSONArray(new PendingPhotos(root).read(shop));assertEquals(2,retained.length());assertTrue(new File(root,"pending-photos/"+broken+".photo").exists());}
 @Test public void missingBinaryDoesNotHideOtherRetainedPhotos() throws Exception {File root=temporary.newFolder();PendingPhotos photos=new PendingPhotos(root);String missing=UUID.randomUUID().toString(),healthy=UUID.randomUUID().toString();assertTrue(photos.save(record(missing),shop));assertTrue(photos.save(record(healthy),shop));File firstMetadata=new File(root,"pending-photos").listFiles((directory,name)->name.endsWith(".json"))[0];missing=firstMetadata.getName().replace(".json","");healthy=new JSONArray(photos.read(shop)).getJSONObject(0).getString("captureId").equals(missing)?new JSONArray(photos.read(shop)).getJSONObject(1).getString("captureId"):new JSONArray(photos.read(shop)).getJSONObject(0).getString("captureId");assertTrue(new File(root,"pending-photos/"+missing+".photo").delete());JSONArray retained=new JSONArray(new PendingPhotos(root).read(shop));assertEquals(1,retained.length());assertEquals(healthy,retained.getJSONObject(0).getString("captureId"));}
 @Test public void captureIdCannotOverwriteASeparateRequestOrPhoto() throws Exception {File root=temporary.newFolder();PendingPhotos photos=new PendingPhotos(root);String id=UUID.randomUUID().toString(),original=record(id);assertTrue(photos.save(original,shop));String changed=new JSONObject(original).put("requestId",UUID.randomUUID().toString()).put("data","data:image/jpeg;base64,BQYHCA==").toString();assertFalse(photos.save(changed,shop));assertArrayEquals(new byte[]{1,2,3,4},Files.readAllBytes(new File(root,"pending-photos/"+id+".photo").toPath()));}
 @Test public void identicalRetryStillSucceedsWhenQueueIsFull() throws Exception {File root=temporary.newFolder();PendingPhotos photos=new PendingPhotos(root);String first=record(UUID.randomUUID().toString());assertTrue(photos.save(first,shop));for(int i=1;i<12;i++)assertTrue(photos.save(record(UUID.randomUUID().toString()),shop));assertTrue(photos.save(first,shop));assertEquals(12,new JSONArray(photos.read(shop)).length());}
 @Test public void changedBinaryIsRetainedButNeverQueuedForUpload() throws Exception {File root=temporary.newFolder();PendingPhotos photos=new PendingPhotos(root);String id=UUID.randomUUID().toString();assertTrue(photos.save(record(id),shop));File file=new File(root,"pending-photos/"+id+".photo");Files.write(file.toPath(),new byte[]{5,6,7,8});assertEquals(0,new JSONArray(new PendingPhotos(root).read(shop)).length());assertTrue(file.exists());}
 @Test public void interruptedMetadataCommitIsRecoveredAfterRestart() throws Exception {File root=temporary.newFolder();String id=UUID.randomUUID().toString();PendingPhotos photos=new PendingPhotos(root);assertTrue(photos.save(record(id),shop));File json=new File(root,"pending-photos/"+id+".json"),journal=new File(root,"pending-photos/"+id+".pending");JSONObject metadata=new JSONObject(new String(Files.readAllBytes(json.toPath()),java.nio.charset.StandardCharsets.UTF_8)).put("byteLength",4).put("sha256","9f64a747e1b97f131fabb6b447296c9b6f0201e79fb3c5356e6c77e89b6a806a");Files.write(journal.toPath(),metadata.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));assertTrue(json.delete());assertEquals(1,new JSONArray(new PendingPhotos(root).read(shop)).length());assertTrue(json.exists());assertFalse(journal.exists());}
}

